import{_ as a,c as t,o as i,ag as n}from"./chunks/framework.ARG558ZT.js";const u=JSON.parse('{"title":"Authentication and Authorization — practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/node-js/module-09-authentication-authorization.md","filePath":"practice/node-js/module-09-authentication-authorization.md"}'),r={name:"practice/node-js/module-09-authentication-authorization.md"};function s(o,e,l,d,c,h){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="authentication-and-authorization-—-practice" tabindex="-1">Authentication and Authorization — practice <a class="header-anchor" href="#authentication-and-authorization-—-practice" aria-label="Permalink to “Authentication and Authorization — practice”">​</a></h1><p><strong>Learner status: still required.</strong> These tasks were separated from the textbook; no completion is credited.</p><p><a href="./../../node-js/module-09-authentication-authorization.html">Textbook explanation</a> · <a href="./">Node.js practice map</a></p><h2 id="graduated-practice-identity-and-access" tabindex="-1">Graduated practice: identity and access <a class="header-anchor" href="#graduated-practice-identity-and-access" aria-label="Permalink to “Graduated practice: identity and access”">​</a></h2><h3 id="_1-worked-example" tabindex="-1">1. Worked example <a class="header-anchor" href="#_1-worked-example" aria-label="Permalink to “1. Worked example”">​</a></h3><p>Follow the browser-session walkthrough near the start of this chapter: anonymous CSRF bootstrap, registration, session regeneration on login, an owner-scoped write and logout. Compare every expected status and cookie change.</p><h3 id="_2-guided-build" tabindex="-1">2. Guided build <a class="header-anchor" href="#_2-guided-build" aria-label="Permalink to “2. Guided build”">​</a></h3><p>Use the retained session application with two independent cookie jars. Hint: a session identifies the caller; the <code>owner_id</code> predicate authorizes the task. <strong>Success:</strong> the owner can update, another signed-in user gets the same 404 as a missing task, and a missing CSRF token returns 403.</p><h3 id="_3-independent-task" tabindex="-1">3. Independent task <a class="header-anchor" href="#_3-independent-task" aria-label="Permalink to “3. Independent task”">​</a></h3><p>Add an authenticated endpoint that renames a task using an allowlisted title. Keep ownership in the UPDATE predicate. <strong>Success:</strong> a hostile title is stored as text, an unknown field is rejected, and another user cannot rename the task even if they know its ID.</p><h3 id="_4-optional-depth-jwt-and-concurrent-access-boundaries" tabindex="-1">4. Optional depth: JWT and concurrent access boundaries <a class="header-anchor" href="#_4-optional-depth-jwt-and-concurrent-access-boundaries" aria-label="Permalink to “4. Optional depth: JWT and concurrent access boundaries”">​</a></h3><p>Use Node 24, TypeScript 5.9, Express 5 and jsonwebtoken 9.0.3 (lock exact resolved versions). Put the verifier, header parser and middleware in separate typed modules and wire the principal adapter shown above. Keep test fixtures outside any Autocode-owned src/tests directory. No actual key or provider credential belongs in the notes.</p><p><strong>Acceptance:</strong> a valid signed 15-minute access token works with Bearer/bearer/BEARER and multiple ASCII spaces while token case remains intact. Reject missing exp/iat/role/purpose, invalid role, malformed subject, future iat/nbf, expired token, wrong issuer/audience/algorithm/key, excessive lifetime and refresh-purpose token. Test the exact expiry and five-second tolerance boundary. Missing/invalid credentials and known disabled users return 401 with the challenge; a thrown verification configuration error or rejected account-store call reaches next(error), never 401 and never the protected handler. Do not log raw credentials. Document revocation/role-change staleness for the chosen lookup policy.</p><p>In an isolated PostgreSQL database create two tenants and owners, perform the conditional update, change ownership between a prior read and write, then prove the old owner cannot update. Other-tenant/missing IDs produce the same no-row result; hostile name text stays a bound value; authorized changes return only id/name. For operations with extra invariants use a conditional version/state predicate or an explicit transaction/lock and test interleavings; authorization does not exempt stock/payment invariants. Record the observed interleavings and results before marking the exercise complete.</p><p>References checked 2026-10-21: <a href="https://github.com/auth0/node-jsonwebtoken" target="_blank" rel="noreferrer">jsonwebtoken verification/options/errors</a>, <a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-11.1" target="_blank" rel="noreferrer">HTTP authentication scheme case</a>, <a href="https://www.rfc-editor.org/rfc/rfc6750.html#section-2.1" target="_blank" rel="noreferrer">Bearer syntax</a>, <a href="https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP authorization</a>, <a href="https://www.postgresql.org/docs/16/transaction-iso.html#XACT-READ-COMMITTED" target="_blank" rel="noreferrer">PostgreSQL Read Committed</a>. The runnable application supplies the session/CSRF and reset workflow. OIDC federation and upload pipelines are separate advanced integrations; this JWT lab does not implement those protocols.</p><hr><h2 id="_16-final-review-checklist" tabindex="-1">16. Final review checklist <a class="header-anchor" href="#_16-final-review-checklist" aria-label="Permalink to “16. Final review checklist”">​</a></h2><h3 id="fundamentals" tabindex="-1">Fundamentals <a class="header-anchor" href="#fundamentals" aria-label="Permalink to “Fundamentals”">​</a></h3><ul><li>[ ] Distinguish authentication from authorization.</li><li>[ ] Explain why missing/invalid credentials normally produce <code>401</code> and insufficient permission produces <code>403</code>.</li><li>[ ] Compare sessions, signed tokens, OIDC, and API keys.</li><li>[ ] Explain why bearer credentials must be protected from theft and replay.</li></ul><h3 id="jwts-and-token-lifecycle" tabindex="-1">JWTs and token lifecycle <a class="header-anchor" href="#jwts-and-token-lifecycle" aria-label="Permalink to “JWTs and token lifecycle”">​</a></h3><ul><li>[ ] Identify JWT header, payload, and signature.</li><li>[ ] Explain why signing is not encryption.</li><li>[ ] Validate algorithm, signature, issuer, audience, expiration, and application claims.</li><li>[ ] Keep claims minimal and non-secret.</li><li>[ ] Explain access-token expiry, refresh rotation, revocation, and replay detection.</li><li>[ ] Describe when server-side session/token state is worth the cost.</li></ul><h3 id="passwords" tabindex="-1">Passwords <a class="header-anchor" href="#passwords" aria-label="Permalink to “Passwords”">​</a></h3><ul><li>[ ] Use a password-specific adaptive hashing function.</li><li>[ ] Explain salts, optional peppers, and work parameters.</li><li>[ ] Know why raw SHA-256 and MD5 are inappropriate for passwords.</li><li>[ ] Hash exactly once and never expose the stored hash.</li><li>[ ] Rate-limit credential endpoints and avoid account-enumeration responses.</li></ul><h3 id="express-implementation" tabindex="-1">Express implementation <a class="header-anchor" href="#express-implementation" aria-label="Permalink to “Express implementation”">​</a></h3><ul><li>[ ] Validate login and registration input.</li><li>[ ] Assign privileged fields on the server, not from public input.</li><li>[ ] Attach a small trusted principal to the request.</li><li>[ ] Apply authentication before authorization.</li><li>[ ] Enforce ownership/tenant filters at the data or use-case boundary.</li><li>[ ] Keep public response objects separate from persistence entities.</li></ul><h3 id="oauth-and-browser-security" tabindex="-1">OAuth and browser security <a class="header-anchor" href="#oauth-and-browser-security" aria-label="Permalink to “OAuth and browser security”">​</a></h3><ul><li>[ ] Distinguish OAuth authorization from OIDC authentication.</li><li>[ ] Use Authorization Code flow with PKCE and validate state/nonce as applicable.</li><li>[ ] Link external accounts by stable issuer and subject.</li><li>[ ] Understand the XSS/CSRF trade-offs of browser token storage.</li><li>[ ] Configure secure cookies deliberately.</li></ul><h3 id="application-and-supply-chain-security" tabindex="-1">Application and supply-chain security <a class="header-anchor" href="#application-and-supply-chain-security" aria-label="Permalink to “Application and supply-chain security”">​</a></h3><ul><li>[ ] Map only allowed public fields instead of assigning an entire request body.</li><li>[ ] Keep caller-controlled paths inside an approved root or generate server-side names.</li><li>[ ] Avoid shell interpretation and validate subprocess arguments and resources.</li><li>[ ] Reject unknown and dangerous object keys before merging data.</li><li>[ ] Restrict outbound URLs and enforce network-level egress controls where possible.</li><li>[ ] Limit and isolate uploads, parsers, regular expressions, and other resource-heavy input.</li><li>[ ] Allowlist redirect destinations.</li><li>[ ] Keep secrets out of builds, source maps, logs, images, and browser bundles.</li><li>[ ] Review dependency and lockfile changes, scan for known risks, and remove unused packages.</li><li>[ ] Trace untrusted data through every privileged sink.</li></ul><p><strong>Check yourself:</strong> explain why deleting only the browser cookie does not revoke a stolen session identifier, why the login POST also needs CSRF protection, and why a session alone does not authorize a task ID.</p><p><strong>Guided exercise:</strong> obtain a recovery token, use it twice, and attempt login with the old and new passwords. <strong>Expected:</strong> first reset 204; second reset 400; old password 401; new password 200; existing session and refresh credentials unusable. Repeat after expiring the reset row in a disposable database. The acceptance runner also races two completions and requires one winner.</p><p><strong>Guided verification:</strong> run the acceptance suite against a disposable PostgreSQL database. It races two calls, requires exactly one fulfillment, then checks that the winner&#39;s replacement is rejected and the family remains revoked after both transactions finish. A mock repository cannot demonstrate row locking or commit behavior.</p>',32)])])}const m=a(r,[["render",s]]);export{u as __pageData,m as default};
